{
  "phase": "ready",
  "section": "final_review",
  "questions": [],
  "summary": "Roadmap updated. Two initiatives: (1) Prototype & Foundations for PoC in May 2026 with mock service and baseline frontend for a single desk/domain; (2) Scenarios MVP for Production in Sep 2026 delivering scenario management, analysis, audit with 7-year retention, configurable sign-off (including Senior Risk Manager role), and micro-frontend integrations with Market Data, FRTB SA, and VaR. One team, 2-week sprints. Dependencies: Prototype before functional epics; Audit before Sign-off; Scenario Management before Analysis.",
  "proposedInitiatives": [
    {
      "title": "Prototype & Foundations (PoC – May 2026)",
      "description": "Validate user flows and data wiring with a mock service and baseline Scenarios frontend for a single desk/domain.",
      "epics": [
        {
          "title": "Create Scenarios Mock Service",
          "description": "Provide mock APIs and data to power PoC flows for scenario list, impact summaries, and approvals."
        },
        {
          "title": "Create Scenarios Frontend",
          "description": "Build the baseline Scenarios micro-frontend with navigation and core UI components for the PoC."
        }
      ]
    },
    {
      "title": "Scenarios MVP – Production Sep 2026",
      "description": "Deliver end-to-end Scenarios for Market Risk with impact review, configurable approvals, and full auditability; integrate with Market Data, FRTB SA, and VaR.",
      "epics": [
        {
          "title": "Build Scenario Management Screen",
          "description": "Enable creation, viewing, and management of scenarios and metadata; link to source change details; prerequisite for analysis."
        },
        {
          "title": "Build Scenario Analysis Screen",
          "description": "Present impact summaries with link-outs to detailed FRTB SA and VaR reports; drill-through from scenarios."
        },
        {
          "title": "Build Audit Functionality",
          "description": "Provide a searchable end-to-end audit trail of messages and actions, including internal e-signoff records with 7-year retention."
        },
        {
          "title": "Build Sign-off Workflow",
          "description": "Implement configurable, rules-based approvals with role- and attribute-level controls; include Senior Risk Manager approval rights."
        },
        {
          "title": "Micro-frontend Integrations (Market Data, FRTB SA, VaR)",
          "description": "Integrate Scenarios with existing UI modules for seamless navigation and context-sharing at production."
        }
      ]
    }
  ],
  "assumptions": [
    "Internal e-signoff and 7-year audit retention are required at launch.",
    "Prototype completes first; Audit precedes Sign-off; Scenario Management precedes Analysis.",
    "One team delivers all work in 2-week sprints.",
    "Architecture decisions (shell, services, audit store, SSO/authorization) will be provided by the architecture team and may affect scope/timelines.",
    "PoC scope is limited to a single desk/domain.",
    "Production target is September 2026 (Q3) and supersedes prior Q4 guidance."
  ],
  "openItems": [
    "Confirm platform architecture details and standards (micro-frontend shell, data services, audit store, SSO/IAM).",
    "Define epic-level acceptance criteria (including compliance and role matrix).",
    "Map precise scope for PoC (May) and UAT (July) across epics and user outcomes.",
    "Align integration timelines and external dependencies with Market Data, FRTB SA, and VaR teams.",
    "Decide whether in-app messaging to promote signed-off changes is in MVP or post-MVP.",
    "Document data residency, privacy, security, and non-functional requirements.",
    "Define success metrics and targets (deferred)."
  ]
}

